diagram('Frostfell 2 · Deep Ice Caves',[
 (470,695,'START · Overlook','See laboratory + far exit','main'),(470,570,'Laboratory rescue','Interrupt Ellis’s transfer','fight'),(470,450,'Confiscated records','Recover while moving forward','main'),(470,330,'Water basin','Move channel → ride platform','main'),(470,205,'Cold-air shutter','Aim freezing area → cross','main'),(770,145,'Officer exit','Three coordinated opponents','fight'),(155,500,'Hugo’s shelf','Optional rope rescue','side'),(155,340,'Safe landing','Rescue route rejoins here','side'),(770,360,'Chiller branch','Optional harder discovery','side')],[(0,1,'main'),(1,2,'main'),(2,3,'main'),(3,4,'main'),(4,5,'main'),(2,6,'side'),(6,7,'side'),(7,3,'side'),(3,8,'side'),(8,4,'side')],'caves.svg')
